#ifndef FONT_H
#define FONT_H

#include "types.h"

// YesOS 8x16 bitmap font (graphics/font_data.c, generated by
// tools/gen_font.py from fonts/yesos-8x16.txt): printable ASCII, the
// Latin-1 letters and signs of Spanish and other Western languages, and €.
// Capitals on rows 2-10, x-height 4-10, baseline row 10, descenders to
// row 13.

#define FONT_WIDTH  8
#define FONT_HEIGHT 16

extern const U8  g_font_8x16[256][16];
// Glyphs beyond U+00FF (the euro sign), looked up by code point.
extern const U32 g_font_extra_count;
extern const U16 g_font_extra_cp[];
extern const U8  g_font_extra[][16];

// Next code point of a UTF-8 string, advancing *s; malformed input gives
// U+FFFD and advances one byte. Never reads past a NUL.
U32       font_utf8_next(const char** s);
// The 16 rows of a code point; '?' for anything the font does not have.
const U8* font_glyph(U32 cp);

#endif // FONT_H
